CREATE COLUMN TABLE "TEST_AP"."OFYM" ("AbsId" INTEGER CS_INT NOT NULL , "Code" NVARCHAR(6) NOT NULL , "Descr" NVARCHAR(30), "StartDate" LONGDATE CS_LONGDATE, "EndDate" LONGDATE CS_LONGDATE, "AssessYear" NVARCHAR(6) NOT NULL , PRIMARY KEY ("AbsId")) UNLOAD PRIORITY 5  AUTO MERGE ;
CREATE UNIQUE INDEX "OFYM_CODE" ON "TEST_AP"."OFYM" ( "Code" ASC );
CREATE UNIQUE INDEX "OFYM_ASSESSYEAR" ON "TEST_AP"."OFYM" ( "AssessYear" ASC )